package dev.redstoneengineering.block;
import com.mojang.serialization.MapCodec;import dev.redstoneengineering.RedstoneEngineering;import dev.redstoneengineering.physics.*;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;
/** Inline pressure-drop/flow proxy instrument. BACK=input, FRONT=output. */
public class PneumaticFlowMeterBlock extends DirectionalDomainBlock{public PneumaticFlowMeterBlock(Properties p){super(p);}@Override public MapCodec<PneumaticFlowMeterBlock> codec(){return RedstoneEngineering.PNEUMATIC_FLOW_METER_CODEC.value();}public static int flowProxy(Level l,BlockPos p){return RuntimeIntStore.get(l,"pneumatic_flow",p,4)[0];}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide){int[]r=RuntimeIntStore.get(l,"pneumatic_flow",p,4);pl.displayClientMessage(Component.literal("Pneumatic flow meter | ΔP="+r[1]+" | flow≈"+r[0]+" | Pin/Pout="+r[2]+"/"+r[3]),true);}return InteractionResult.sidedSuccess(l.isClientSide);}}
